INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷112·太祖本纪三·广顺三年闰月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/14cbc2e919886dae0472b77f2330611d8b32c8d7/content/books/zizhi-tongjian/vol-291/year-0953/part-01/sources/library/jiuwudaishi-112-intercalary-953/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺三年闰月，段落 jiu-wudaishi-205deb4a7860-p002682；已核上下文及传主，纸本及异文待核。", "id": "045038f4-bcaa-5353-98d6-005547836496"}, {"title": "宋史·卷278·列传第三十七·马全义早年", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/14cbc2e919886dae0472b77f2330611d8b32c8d7/content/books/zizhi-tongjian/vol-291/year-0953/part-01/sources/library/songshi-278-maquanyi-early/source.txt", "note": "《宋史》卷278·列传第三十七·马全义早年，段落 songshi-9c6e46fee832-p059504；已核上下文及传主，纸本及异文待核。", "id": "3b5773e3-6f74-588d-8a51-5fc2d5e6cbb3"}, {"title": "宋史·卷278·列传第三十七·马全义事周", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/14cbc2e919886dae0472b77f2330611d8b32c8d7/content/books/zizhi-tongjian/vol-291/year-0953/part-01/sources/library/songshi-278-maquanyi-zhou/source.txt", "note": "《宋史》卷278·列传第三十七·马全义事周，段落 songshi-9c6e46fee832-p059505；已核上下文及传主，纸本及异文待核。", "id": "d77f2a55-15d2-5bb3-9500-2f66b05393db"}, {"title": "资治通鉴·卷291·广顺三年正月至闰正月", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/14cbc2e919886dae0472b77f2330611d8b32c8d7/content/books/zizhi-tongjian/vol-291/year-0953/part-01/sources/library/tongjian-291-953-january-intercalary/source.txt", "note": "《资治通鉴》卷291·广顺三年正月至闰正月，段落 zizhi-tongjian-a63549944a71-p003455；已核上下文及传主，纸本及异文待核。", "id": "07c464bb-e6ff-59c9-85b5-96bfdf715a66"}, {"title": "旧五代史·卷112·太祖本纪三·广顺三年正月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/13c4dafe3d5c65d384d4d803f7681d5baf78489e/content/books/zizhi-tongjian/vol-291/year-0952/part-02/sources/library/jiuwudaishi-112-january-953-yeji/source.txt", "note": "《旧五代史》卷112·太祖本纪三·广顺三年正月，段落 jiu-wudaishi-205deb4a7860-p002681；已核上下文及传主，纸本及异文待核。", "id": "2d7ae78a-ac67-562a-aa5e-6b532a2abaee"}]'::jsonb)
