INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "刘言", "aliases": ["劉言"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吉州庐陵人，楚国辰州刺史。951年王逵、周行逢等欲迎他到朗州任副使，他单骑前往，众人废去马光惠后推他为权武平留后。生卒年尚未录入。", "biography": null, "status": "draft", "id": "b32e335e-b386-5ab9-a996-bb31d55c6787"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "何敬真", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "武陵人，朗州步军指挥使。950年率部族兵攻破韩礼在杨柳桥的防线；马希萼入长沙后任他为朗州牙内都指挥使，率兵戍守。生卒年未载。", "biography": null, "status": "draft", "id": "0ce9ccfa-b68b-575c-96b0-8022528be7ad"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "张亻放（楚军指挥使）", "aliases": ["张仿", "張仿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国诸军指挥使。951年与王逵、周行逢、何敬真共同处理朗州军府事务。电子底本姓名末字写作“亻放”，字形待核，暂不与其他记载中的张仿合并。生卒年未载。", "biography": null, "status": "draft", "id": "b66c1113-4e1b-5c98-9a58-2258c1bad288"}, {"name": "朱全琇", "aliases": ["硃全琇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州牙将。952年与王逵等受刘言任命为指挥使，姓名底本写硃全琇。生卒年未载。", "biography": null, "status": "draft", "id": "88df4471-92c7-542f-b91b-ec31a9110353"}, {"name": "折从远", "aliases": ["折從遠", "折从阮", "折從阮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，府州刺史。后晋割让北地后，府州归属契丹。他据险抵制契丹迁民，后奉石重贵命令攻入契丹境内、拔十余寨，944年六月戊午任府州团练使。《新五代史》明确其后因避汉高祖名改称折从阮，字可久。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "500d7480-2e3a-5553-9370-8e4295db3cc1"}, {"name": "李万全", "aliases": ["李萬全"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "野鸡族首领之一。953年正月折从阮奏报其已接受后周诏书并立誓。具体族属不作现代归类，生卒年未载。", "biography": null, "status": "draft", "id": "e37b77c0-ade8-51b9-b8a9-e5c0fbcd65ce"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "张凝", "aliases": ["張凝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周阁门使。951年十二月奉郭威之命率兵到郓州巡检，以防备慕容彦超。生卒年未载。", "biography": null, "status": "draft", "id": "ad0d7bc5-f6cc-5321-9e2a-93f97ff1fec6"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "叶仁鲁", "aliases": ["葉仁魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的亲将。947年率三千步骑救援承天军，在契丹兵外出劫掠时将其击败，四月丁丑收复承天军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "6dacd8bb-f8c1-5bac-ab79-aa47a13e5a06"}, {"name": "王峻", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "安阳人，刘知远的客将。947年奉三表赴契丹，报告贺入大梁、暂不离太原及贡路受阻。《旧五代史》称牙将王峻，记二月出使和携杖回太原。生卒年本段未核。", "biography": null, "status": "draft", "id": "196d9879-50e7-5ff5-9d99-4879fa1ea3a2"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "杨弘裕", "aliases": ["楊弘裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周定和都指挥使。953年契丹围义丰军时夜袭敌营，获胜使契丹撤走。生卒年未载。", "biography": null, "status": "draft", "id": "5bb85fe0-f5e3-5d91-b93a-0952278400f1"}, {"name": "马全乂", "aliases": ["馬全乂", "马全义", "馬全義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "原为李守贞麾下骑士，后事柴荣。953年随柴荣入朝，郭威召见并任命为殿前指挥使，称赞其忠于所事。《宋史》作马全义，记同一河中经历、任职和召见言论，复用同人异名；后续生卒另待录。", "biography": null, "status": "draft", "id": "dac95b9c-875b-5289-a14d-87b438c324fb"}, {"name": "高允权", "aliases": ["高允權"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高万金之子。947年延州军队攻周密，高允权获推为留后、据西城。《通鉴》称录事参军，《新五代史》追记开运时任肤施令、罢后居家，任职时点及写法分别保留。生卒年暂未录入。", "biography": null, "status": "draft", "id": "be6f380e-7cd3-5e5e-87d2-900104d55f65"}, {"name": "高绍基", "aliases": ["高紹基"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "雄武节度使高允权之子、牙内指挥使。953年父死后图谋继任，隐瞒父丧，杀死劝谏的观察判官李彬并诬报谋反；朝廷派张仁谦巡检后才公开父丧。生卒年未载。", "biography": null, "status": "draft", "id": "e323db07-2f72-541e-ac62-3a221bd23837"}, {"name": "李彬（延州观察判官）", "aliases": ["李彬（延州觀察判官）"], "era": "五代十国", "birth_year": null, "death_year": 953, "description": "雄武军观察判官。953年劝谏高绍基隐瞒父丧谋求继任，被高绍基杀死，并被诬报为谋反者。生年未载，不与其他同名人物混同。", "biography": null, "status": "draft", "id": "1741c213-f479-57e8-96da-e1eaea74145f"}, {"name": "张仁谦", "aliases": ["張仁謙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。《宋史》陈思让传记他于951年与陈思让、向训等率军在虒亭西迎战北汉。生卒年未载。", "biography": null, "status": "draft", "id": "3c908e76-fb6b-5120-a480-5eada2c5ad92"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
